#!/usr/bin/env python3
"""FS3 v161 - the weapon overhaul.

    Turrets   capital ships carry FreeSpace guns, one per mount, each at its
              own beat: Terran Turret and Terran Huge Turret for Terrans and
              Vasudans, Shivan Turret Laser and Megafunk for Shivans.
              Cruisers and corvettes light guns only; destroyers, stations
              and bosses a heavy one on every third mount; the Orion fires
              hers in threes. Own sounds (the Megafunk shares the Shivan
              turret sound). Colours: Terrans blue, Vasudans yellow/orange,
              Shivans red.
    Defence   capital ships of both sides shoot at bombs coming in first,
              the player's too.
    Flak      the flak of capital ships is the Dante: shell, colours, sound.
    Shivans   fighters and bombers fly Shivan Light, Heavy and Mega lasers
              (red, own sounds) and the same missiles and bombs as everyone
              else. Nephilim and Seraphim carry a dorsal turret with a Light
              Laser (mount data updated).
    Colours   every gun fires in its own colours; missiles and bombs show the
              colour of their race (the NTF blue, as Terrans).
    Lasers    all bolts: a fading trail, a hot core, sparks, a flash at the
              muzzle and a spray in their colour where they strike.
    Armour    shrapnel keeps 30 % instead of 60 % of the gun factor against
              capital hulls (Dante, Infyrno, flak).
    Knossos   a ship going through the portal jumps into a turquoise vortex
              ahead of her instead of the old one under her.
    Log       the secondary is named even before one was chosen.

Needs v160. Edits src/12_audio.js, src/20_render.js, src/40_world.js,
src/50_combat.js, src/55_arms.js, src/60_effects.js, src/70_ui.js and
hlp_mounts_final.json in place, adds src/57_turrets.js and writes the
updated fieldsim.js, wpnsim.js and warpsim.js. Run assemble.py afterwards.
New sounds (fs3_sounds_turrets.zip) are already on the server.
"""
import base64
import json
import os
import sys

if "HULL_ARMOR" not in open("src/55_arms.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v160 einspielen.")
if os.path.exists("src/57_turrets.js"):
    sys.exit("Abbruch: v161 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)

# ── Mounts: the dorsal turrets of Nephilim and Seraphim (Silvio's marks) ──
MJ = "hlp_mounts_final.json"
load(MJ)
_m = json.loads(F[MJ])
for _k, _p in (("bonephilim", {"dx": 0.052, "dy": -0.108}), ("boseraphim", {"dx": -0.401, "dy": -0.579})):
    if _k not in _m:
        sys.exit("Abbruch (Mounts): %s fehlt." % _k)
    _m[_k]["turret"] = [_p]
F[MJ] = json.dumps(_m, indent=2, ensure_ascii=False) + ("\n" if F[MJ].endswith("\n") else "")

